// Helpers aligned with C# SimulatorApp

static DWORD ParseIpv4(const CString& s) {
    DWORD ip=0; int parts[4]={0},n=0; CString token;
    for (int i=0;i<s.GetLength();i++){ TCHAR c=s[i];
        if (c>=_T('0')&&c<=_T('9'))token+=c;
        else if(c==_T('.')&&n<4){parts[n++]=_ttoi(token);token.Empty();}
    } if(n<4)parts[n]=_ttoi(token);
    ip=(parts[0]<<24)|(parts[1]<<16)|(parts[2]<<8)|parts[3];return ip;
}

static void ParseMac(const CString& mac,BYTE out[6]) {
    memset(out,0xFF,6);int val[6]={0},n=0;CString token;
    for(int i=0;i<mac.GetLength()&&n<6;i++){TCHAR c=mac[i];
        if((c>=_T('0')&&c<=_T('9'))||(c>=_T('A')&&c<=_T('F'))||(c>=_T('a')&&c<=_T('f')))token+=c;
        else if((c==_T(':')||c==_T('-'))&&!token.IsEmpty()){_stscanf_s(token,_T("%x"),&val[n++]);token.Empty();}
    } if(n<6&&!token.IsEmpty())_stscanf_s(token,_T("%x"),&val[n]);
    for(int i=0;i<6;i++)out[i]=(BYTE)val[i];
}

static void SetDestMac(BYTE*f,int l,const BYTE m[6]){if(l>=6)memcpy(f,m,6);}
static void SetDestIp(BYTE*f,int l,DWORD ip){if(l>=34){f[30]=(BYTE)(ip>>24);f[31]=(BYTE)(ip>>16);f[32]=(BYTE)(ip>>8);f[33]=(BYTE)ip;}}

static unsigned int DetectChecksumFlags(const BYTE*f,int l){
    if(l<14)return 0; unsigned short et=(f[12]<<8)|f[13];
    if(et==0x0800&&l>=34){unsigned char p=f[23];unsigned int fl=0x01;
        if(p==1)fl|=0x02;if(p==6)fl|=0x10;if(p==17)fl|=0x08;return fl;}
    if(et==0x86DD&&l>=54)return 0x02;return 0;
}

static CString GetProtocolName(const BYTE*f,int l){
    if(l<14)return _T("?");unsigned short et=(f[12]<<8)|f[13];
    if(et==0x0800&&l>=34){switch(f[23]){case 1:return _T("ICMP");case 6:return _T("TCP");case 17:return _T("UDP");default:return _T("IP");}}
    if(et==0x0806)return _T("ARP");if(et==0x86DD)return _T("IPv6");return _T("Eth");
}

static CString IpToStr(DWORD ip){CString s;s.Format(_T("%d.%d.%d.%d"),(ip>>24)&0xFF,(ip>>16)&0xFF,(ip>>8)&0xFF,ip&0xFF);return s;}

static CString GetFriendlyName(const char* pcapName)
{
    CString s(pcapName);
    int gs = s.Find(_T('{'));
    int ge = s.Find(_T('}'));
    if (gs >= 0 && ge > gs)
    {
        // ×¢ï¿½ï¿½ï¿½ Network\{4D36E972-...}\{NIC_GUID}\Connection ï¿½Ú¶ï¿½ï¿½ï¿½ GUID ï¿½ï¿½ï¿½ëº¬ {}ï¿½ï¿½
        // Ö®Ç° Mid(gs+1, ge-gs-1) È¥ï¿½ï¿½ï¿½Ë»ï¿½ï¿½ï¿½ï¿½Åµï¿½ï¿½ï¿½ RegOpenKeyEx ï¿½ï¿½Ô¶Ê§ï¿½Ü¡ï¿½
        CString guid = s.Mid(gs, ge - gs + 1);
        guid.MakeUpper();
        HKEY hKey;
        CString regPath;
        regPath.Format(_T("SYSTEM\\CurrentControlSet\\Control\\Network\\{4D36E972-E325-11CE-BFC1-08002BE10318}\\%s\\Connection"), guid);
        if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, regPath, 0, KEY_READ, &hKey) == ERROR_SUCCESS)
        {
            TCHAR name[256] = {0};
            DWORD size = sizeof(name);
            LONG rc = RegQueryValueEx(hKey, _T("Name"), NULL, NULL, (LPBYTE)name, &size);
            RegCloseKey(hKey);
            if (rc == ERROR_SUCCESS && name[0] != 0)
                return CString(name);
        }
    }
    // ï¿½ï¿½ï¿½Ë£ï¿½ï¿½ï¿½ï¿½ï¿½Ô­Ê¼ pcap ï¿½ï¿½ï¿½ï¿½ANSI -> TCHARï¿½ï¿½
    return CString(pcapName);
}

