void CRawPacketDlg::OnDestroy()
{
    if (m_isRunning) OnStop();
    if (m_nStatsTimer) { KillTimer(m_nStatsTimer); m_nStatsTimer = 0; }
    UnloadRawPacketEngine();
    CDialog::OnDestroy();
}

void CRawPacketDlg::LoadBuiltinPackets()
{
    for (int i=0; i<_countof(kAttackPackets); ++i)
    {
        const AttackPacketDef& def=kAttackPackets[i];
        CString text; text.Format(_T("%s  [%s]"), def.name, def.os);
        int idx=m_listPackets.InsertItem(i,text);
        m_listPackets.SetCheck(idx,FALSE);
        BuiltinPacket bp;
        bp.id=i; bp.name=def.name; bp.targetOs=def.os;
        bp.resourceName.Empty(); bp.selected=false;
        bp.checksumFlags=0;
        // Combine all streams for this attack type
        for (int s=0; s<def.streamCount; s++) {
            bp.packetData.insert(bp.packetData.end(), def.streams[s], def.streams[s]+def.lens[s]);
            bp.rules.insert(bp.rules.end(), def.rules[s], def.rules[s]+def.ruleCounts[s]);
            if (bp.checksumFlags==0) bp.checksumFlags=def.flags[s];
        }
        m_builtinPackets.push_back(bp);
    }
}



bool CRawPacketDlg::LoadRawPacketEngine()
{
    m_hRpeDll = LoadLibrary(_T("RawPacketEngine.dll"));
    if (!m_hRpeDll) return false;
    #define LOAD(n) n = (pfn##n)GetProcAddress(m_hRpeDll, #n); if (!n) return false
    LOAD(RPE_Init); LOAD(RPE_Cleanup); LOAD(RPE_GetAdapterCount);
    LOAD(RPE_GetAdapterInfo); LOAD(RPE_SelectAdapter); LOAD(RPE_AddStream);
    LOAD(RPE_ClearStreams); LOAD(RPE_SetRateConfig); LOAD(RPE_Start);
    LOAD(RPE_Stop); LOAD(RPE_GetStats);
    return true;
}

void CRawPacketDlg::UnloadRawPacketEngine()
{
    if (m_hRpeDll) { FreeLibrary(m_hRpeDll); m_hRpeDll = NULL; }
}

void CRawPacketDlg::RefreshAdapterList()
{
    m_cbAdapter.ResetContent();
    m_adapterNames.RemoveAll();
    m_adapterIps.RemoveAll();
    if (!RPE_GetAdapterCount) return;
    int count = RPE_GetAdapterCount();
    for (int i = 0; i < count; ++i)
    {
        char name[512]={0}, ip[64]={0};
        RPE_GetAdapterInfo(i,name,sizeof(name),ip,sizeof(ip));
        if (ip[0]==0||strcmp(ip,"0.0.0.0")==0) continue;
        if (strncmp(ip,"127.",4)==0) continue;
        CString friendly=GetFriendlyName(name);
        CString display; display.Format(_T("#%d %s  (%S)"),i,friendly,ip);
        m_cbAdapter.AddString(display);
        m_adapterNames.Add(CString(name));
        m_adapterIps.Add(CString(ip));
    }
    if (count > 0)
    {
        m_cbAdapter.SetCurSel(0);
        m_selectedAdapterIndex = 0;
        if (RPE_SelectAdapter) RPE_SelectAdapter(0);
    }
}

void CRawPacketDlg::OnCbnSelchangeAdapter()
{
    int sel = m_cbAdapter.GetCurSel();
    if (sel >= 0 && RPE_SelectAdapter) { m_selectedAdapterIndex = sel; RPE_SelectAdapter(sel); }
}

void CRawPacketDlg::OnBnClickedStart() { if (!m_isRunning) OnStart(); }
void CRawPacketDlg::OnBnClickedStop()  { if (m_isRunning) OnStop(); }

void CRawPacketDlg::OnStart()
{
    if (!RPE_ClearStreams||!RPE_AddStream) return;
    for (int i=0; i<(int)m_builtinPackets.size(); ++i)
        m_builtinPackets[i].selected=m_listPackets.GetCheck(i)!=FALSE;
    RPE_ClearStreams();

    BYTE dstMac[6]={0xFF,0xFF,0xFF,0xFF,0xFF,0xFF};
    CString strMac; m_editDestMac.GetWindowText(strMac);
    if (!strMac.IsEmpty()) ParseMac(strMac,dstMac);
    CString strIp; m_editDestIp.GetWindowText(strIp);
    DWORD dstIp=0; if (!strIp.IsEmpty()) dstIp=ParseIpv4(strIp);

    WritePrivateProfileString(_T("RawPacket"),_T("DestIp"),strIp,m_iniPath);
    WritePrivateProfileString(_T("RawPacket"),_T("DestMac"),strMac,m_iniPath);

    CWnd* pListRight=GetDlgItem(IDC_LIST_RP_RIGHT);
    CListCtrl* pLC=pListRight?(CListCtrl*)pListRight:NULL;
    if (pLC) pLC->DeleteAllItems();

    int streamCount=0;
    for (size_t i=0; i<m_builtinPackets.size(); ++i)
    {
        if (!m_builtinPackets[i].selected) continue;
        std::vector<BYTE>& pkt=m_builtinPackets[i].packetData;
        if (pkt.empty()) continue;
        SetDestMac(pkt.data(),(int)pkt.size(),dstMac);
        SetDestIp(pkt.data(),(int)pkt.size(),dstIp);
        unsigned int cksum=DetectChecksumFlags(pkt.data(),(int)pkt.size());
        if (cksum==0) cksum=m_builtinPackets[i].checksumFlags;
        std::vector<RpeRule>& rules=m_builtinPackets[i].rules;
        const RpeRule* rp=rules.empty()?NULL:rules.data();
        int rc=(int)rules.size();
        CStringA name(m_builtinPackets[i].name);
        int ret=RPE_AddStream(pkt.data(),(int)pkt.size(),name,(void*)rp,rc,cksum);
        if (ret>=0) {
            streamCount++;
            if (pLC) {
                DWORD src=0,dst=0;
                if (pkt.size()>=34) {
                    src=(pkt[26]<<24)|(pkt[27]<<16)|(pkt[28]<<8)|pkt[29];
                    dst=(pkt[30]<<24)|(pkt[31]<<16)|(pkt[32]<<8)|pkt[33];
                }
                int row=pLC->InsertItem(streamCount-1,_T(""));
                CString s; s.Format(_T("%d"),streamCount); pLC->SetItemText(row,0,s);
                pLC->SetItemText(row,1,m_builtinPackets[i].name);
                pLC->SetItemText(row,2,IpToStr(src));
                pLC->SetItemText(row,3,IpToStr(dst));
                pLC->SetItemText(row,4,GetProtocolName(pkt.data(),(int)pkt.size()));
                s.Format(_T("%d"),(int)pkt.size()); pLC->SetItemText(row,5,s);
                pLC->SetItemText(row,6,_T("Builtin"));
            }
        }
    }
    if (streamCount==0) { AfxMessageBox(_T("Select at least one attack packet"),MB_ICONWARNING); return; }

    CString strSpeed; m_editSpeedValue.GetWindowText(strSpeed); long long speedVal=_ttoi64(strSpeed);
    int speedMode=m_cbSpeedMode.GetCurSel(); int sendMode=m_cbSendMode.GetCurSel();
    CString strBurst; m_editBurstCount.GetWindowText(strBurst); long long burstCnt=_ttoi64(strBurst);
    if (RPE_SetRateConfig) RPE_SetRateConfig(speedMode,speedVal,sendMode,burstCnt);
    if (RPE_Start&&RPE_Start()==0) {
        m_isRunning=true; m_startTick=GetTickCount(); m_lastSendTotal=0; m_lastSendBytes=0;
        m_btnStart.EnableWindow(FALSE); m_btnStop.EnableWindow(TRUE);
        m_stStatus.SetWindowText(_T("Running...")); m_nStatsTimer=SetTimer(1,1000,NULL);
    } else { m_stStatus.SetWindowText(_T("Start failed")); }
}

void CRawPacketDlg::OnStop()
{
    if (m_nStatsTimer) { KillTimer(m_nStatsTimer); m_nStatsTimer = 0; }
    if (RPE_Stop) RPE_Stop();
    m_isRunning = false;
    m_btnStart.EnableWindow(TRUE);
    m_btnStop.EnableWindow(FALSE);
    m_stStatus.SetWindowText(_T("Stopped"));
    UpdateStats();
}

void CRawPacketDlg::OnTimer(UINT_PTR nIDEvent)
{
    if (nIDEvent == 1 && m_isRunning) UpdateStats();
    CDialog::OnTimer(nIDEvent);
}

void CRawPacketDlg::UpdateStats()
{
    if (!RPE_GetStats) return;
    unsigned long long total=0,bytes=0,fail=0;
    RPE_GetStats(&total,&bytes,&fail);
    DWORD now=GetTickCount();
    double elapsedSec=(now-m_startTick)/1000.0;
    if (elapsedSec<=0) elapsedSec=1.0;
    unsigned long long deltaTotal=total-m_lastSendTotal;
    unsigned long long deltaBytes=bytes-m_lastSendBytes;
    double curPps=(double)deltaTotal;
    double curBps=(double)deltaBytes*8.0;
    double avgPps=(double)total/elapsedSec;
    double avgBps=(double)bytes*8.0/elapsedSec;
    m_lastSendTotal=total; m_lastSendBytes=bytes;
    CString s;
    s.Format(_T("%.0f"),curBps); m_stBps.SetWindowText(s);
    s.Format(_T("%.0f"),curPps); m_stPps.SetWindowText(s);
    s.Format(_T("%llu"),total);  m_stTotal.SetWindowText(s);
    s.Format(_T("%llu"),fail);   m_stFail.SetWindowText(s);
    s.Format(_T("%.0f"),avgBps); m_stAvgBps.SetWindowText(s);
    s.Format(_T("%.0f"),avgPps); m_stAvgPps.SetWindowText(s);
}

